import type { ReactNode } from 'react'
import { HelpCircle, Percent, ReceiptText, Store, Truck } from 'lucide-react'
import { AnimatePresence, motion } from 'motion/react'
import { categories, shopTypeLabels, type ShopType } from '../../data/categories'
import { PAYMENT_FEE_RATE, type PricingInput } from '../../lib/pricing'
import {
  clamp,
  formatRatePercent,
  formatVnd,
  toWholeVnd,
} from '../../lib/utils'
import { Badge } from '../ui/badge'
import { Button } from '../ui/button'
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from '../ui/card'
import { Input } from '../ui/input'
import { RadioGroup, RadioGroupItem } from '../ui/radio-group'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '../ui/select'
import { Slider } from '../ui/slider'
import { Switch } from '../ui/switch'
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '../ui/tooltip'
import { CurrencyInput } from './CurrencyInput'

export type ProfitMode = 'percent' | 'amount'

type InputCardProps = {
  shopType: ShopType
  onShopTypeChange: (value: ShopType) => void
  categoryIndex: number
  onCategoryChange: (index: number) => void
  cogs: number
  onCogsChange: (value: number) => void
  profitMode: ProfitMode
  onProfitModeChange: (mode: ProfitMode) => void
  profitPercent: number
  onProfitPercentChange: (value: number) => void
  profitAmount: number
  onProfitAmountChange: (value: number) => void
  serviceFeeEnabled: boolean
  onServiceFeeEnabledChange: (value: boolean) => void
  serviceFee: number
  onServiceFeeChange: (value: number) => void
  buyerShipping: number
  onBuyerShippingChange: (value: number) => void
  pricingInput: PricingInput
}

export function InputCard({
  shopType,
  onShopTypeChange,
  categoryIndex,
  onCategoryChange,
  cogs,
  onCogsChange,
  profitMode,
  onProfitModeChange,
  profitPercent,
  onProfitPercentChange,
  profitAmount,
  onProfitAmountChange,
  serviceFeeEnabled,
  onServiceFeeEnabledChange,
  serviceFee,
  onServiceFeeChange,
  buyerShipping,
  onBuyerShippingChange,
  pricingInput,
}: InputCardProps) {
  const selectedCategory = categories[categoryIndex]
  const selectedFeeRate = selectedCategory[shopType]
  const sliderValue = clamp(profitPercent, 0, 50)

  return (
    <Card className="overflow-hidden">
      <CardHeader className="relative overflow-hidden border-b border-white/70 bg-white/70">
        <div className="pointer-events-none absolute inset-x-0 top-0 h-px bg-[linear-gradient(90deg,transparent,rgba(238,77,45,0.72),rgba(6,182,212,0.62),transparent)]" />
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div>
            <CardTitle className="text-2xl font-black tracking-tight">
              Pricing Inputs
            </CardTitle>
            <CardDescription className="font-medium">
              Tính ngược giá bán từ vốn, lợi nhuận mục tiêu và phí Shopee.
            </CardDescription>
          </div>
          <Badge className="border-shopee/20 bg-shopee-soft/90 text-shopee">
            {formatRatePercent(selectedFeeRate)}
          </Badge>
        </div>
      </CardHeader>

      <CardContent className="space-y-5 p-5 pt-5 sm:p-6">
        <motion.div
          initial={{ opacity: 0, y: 14 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.05, duration: 0.38 }}
          className="space-y-2"
        >
          <LabelRow icon={<Store className="h-4 w-4" />} label="Shop Type" />
          <RadioGroup
            value={shopType}
            onValueChange={(value) => onShopTypeChange(value as ShopType)}
            className="grid grid-cols-2 rounded-lg border border-white/70 bg-slate-100/80 p-1 shadow-inner"
          >
            {(['normal', 'mall'] as ShopType[]).map((type) => (
              <RadioGroupItem key={type} value={type}>
                {shopTypeLabels[type]}
              </RadioGroupItem>
            ))}
          </RadioGroup>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 14 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1, duration: 0.38 }}
          className="grid gap-4 sm:grid-cols-2"
        >
          <div className="space-y-2 sm:col-span-2">
            <LabelRow icon={<ReceiptText className="h-4 w-4" />} label="Category" />
            <Select
              value={String(categoryIndex)}
              onValueChange={(value) => onCategoryChange(Number(value))}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {categories.map((category, index) => (
                  <SelectItem key={category.name} value={String(index)}>
                    <span className="flex w-full items-center justify-between gap-4">
                      <span>{category.name}</span>
                      <span className="font-semibold text-shopee">
                        {formatRatePercent(category[shopType])}
                      </span>
                    </span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2 sm:col-span-2">
            <LabelRow label="COGS (V)" />
            <CurrencyInput id="cogs" value={cogs} onValueChange={onCogsChange} />
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 14 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.15, duration: 0.38 }}
          className="space-y-4 rounded-lg border border-white/75 bg-white/58 p-4 shadow-soft"
          layout
        >
          <div className="flex flex-wrap items-center justify-between gap-3">
            <LabelRow icon={<Percent className="h-4 w-4" />} label="Profit (L)" />
            <div className="flex rounded-lg border border-white/70 bg-slate-100/80 p-1 shadow-inner">
              <Button
                type="button"
                size="sm"
                variant={profitMode === 'percent' ? 'primary' : 'ghost'}
                onClick={() => onProfitModeChange('percent')}
              >
                %
              </Button>
              <Button
                type="button"
                size="sm"
                variant={profitMode === 'amount' ? 'primary' : 'ghost'}
                onClick={() => onProfitModeChange('amount')}
              >
                VND
              </Button>
            </div>
          </div>

          <Slider
            min={0}
            max={50}
            step={0.5}
            value={[sliderValue]}
            onValueChange={([value]) => onProfitPercentChange(value)}
          />

          <div className="grid gap-3 sm:grid-cols-[1fr_auto] sm:items-center">
            <AnimatePresence mode="wait" initial={false}>
              {profitMode === 'percent' ? (
                <motion.div
                  key="profit-percent"
                  initial={{ opacity: 0, x: -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: 10 }}
                  transition={{ duration: 0.2 }}
                  className="relative"
                >
                  <Input
                    inputMode="decimal"
                    value={Number.isFinite(profitPercent) ? profitPercent : 0}
                    onChange={(event) =>
                      onProfitPercentChange(clamp(Number(event.target.value), 0, 50))
                    }
                    className="pr-10 font-semibold tabular-nums"
                  />
                  <span className="pointer-events-none absolute inset-y-0 right-3 flex items-center text-sm font-semibold text-slate-400">
                    %
                  </span>
                </motion.div>
              ) : (
                <motion.div
                  key="profit-amount"
                  initial={{ opacity: 0, x: -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  exit={{ opacity: 0, x: 10 }}
                  transition={{ duration: 0.2 }}
                >
                  <CurrencyInput
                    value={profitAmount}
                    onValueChange={(value) => onProfitAmountChange(value)}
                  />
                </motion.div>
              )}
            </AnimatePresence>
            <p className="text-sm font-medium text-slate-600">
              = {formatVnd(pricingInput.targetProfit)} per item
            </p>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0, y: 14 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2, duration: 0.38 }}
          className="grid gap-4 sm:grid-cols-2"
        >
          <div className="space-y-3 rounded-lg border border-white/75 bg-white/52 p-4 shadow-soft transition-transform duration-200 hover:-translate-y-0.5">
            <div className="flex items-center justify-between gap-3">
              <div>
                <LabelRow label="Service Fee (Fd)" />
                <p className="mt-1 text-xs text-slate-500">Use Freeship/Voucher Xtra</p>
              </div>
              <Switch
                checked={serviceFeeEnabled}
                onCheckedChange={onServiceFeeEnabledChange}
                aria-label="Toggle service fee"
              />
            </div>
            {serviceFeeEnabled ? (
              <CurrencyInput
                value={serviceFee}
                onValueChange={(value) => onServiceFeeChange(toWholeVnd(value))}
              />
            ) : (
              <div className="rounded-md bg-slate-100/80 px-3 py-3 text-sm font-semibold text-slate-500 shadow-inner">
                0 VND
              </div>
            )}
          </div>

          <div className="space-y-3 rounded-lg border border-white/75 bg-white/52 p-4 shadow-soft transition-transform duration-200 hover:-translate-y-0.5">
            <div className="flex items-center justify-between gap-2">
              <LabelRow icon={<Truck className="h-4 w-4" />} label="Buyer Shipping (S)" />
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <button
                      type="button"
                      className="rounded-full text-slate-400 transition-colors hover:text-shopee focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-shopee focus-visible:ring-offset-2"
                      aria-label="Buyer shipping fee note"
                    >
                      <HelpCircle className="h-4 w-4" />
                    </button>
                  </TooltipTrigger>
                  <TooltipContent>
                    Shopee charges a {formatRatePercent(PAYMENT_FEE_RATE)} payment fee
                    on this amount.
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            </div>
            <CurrencyInput value={buyerShipping} onValueChange={onBuyerShippingChange} />
          </div>
        </motion.div>
      </CardContent>
    </Card>
  )
}

function LabelRow({ icon, label }: { icon?: ReactNode; label: string }) {
  return (
    <label className="flex items-center gap-2 text-sm font-semibold text-slate-700">
      {icon ? <span className="text-shopee">{icon}</span> : null}
      {label}
    </label>
  )
}
