'use client'

import type { ReactNode } from 'react'
import { LogOut, ShieldCheck, Sparkles } from 'lucide-react'
import { motion } from 'motion/react'
import { useRouter } from 'next/navigation'
import { authClient } from '../../lib/auth-client'
import { Button } from '../ui/button'

type AppShellProps = {
  children: ReactNode
}

export function AppShell({ children }: AppShellProps) {
  const router = useRouter()
  const { data: session } = authClient.useSession()
  const userLabel = session?.user.name || session?.user.email || 'Pricing desk'

  async function handleLogout() {
    await authClient.signOut()
    router.replace('/login')
  }

  return (
    <main className="premium-stage min-h-screen overflow-hidden text-slate-950">
      <div className="pointer-events-none absolute inset-0 bg-[linear-gradient(130deg,rgba(238,77,45,0.12)_0%,rgba(255,255,255,0)_32%,rgba(6,182,212,0.13)_68%,rgba(16,185,129,0.10)_100%)]" />
      <div className="pointer-events-none absolute inset-x-0 top-0 h-40 bg-[linear-gradient(180deg,rgba(255,255,255,0.92),rgba(255,255,255,0))]" />

      <motion.nav
        initial={{ opacity: 0, y: -16 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.45, ease: [0.22, 1, 0.36, 1] }}
        className="relative z-20 mx-auto flex w-full max-w-7xl items-center justify-between gap-4 px-4 py-4 sm:px-6 lg:px-8"
      >
        <div className="flex min-w-0 items-center gap-3">
          <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-lg bg-shopee text-white shadow-brand">
            <ShieldCheck className="h-5 w-5" />
          </div>
          <div className="min-w-0">
            <p className="truncate text-sm font-black tracking-wide text-slate-950">
              Shopee Pricing Desk
            </p>
            <p className="truncate text-xs font-semibold text-slate-500">{userLabel}</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <div className="hidden items-center gap-2 rounded-lg border border-white/70 bg-white/70 px-3 py-2 text-xs font-bold text-slate-600 shadow-soft backdrop-blur-md sm:flex">
            <Sparkles className="h-3.5 w-3.5 text-cyan-600" />
            Live margin model
          </div>
          <Button type="button" variant="outline" size="sm" onClick={handleLogout}>
            <LogOut className="h-4 w-4" />
            Logout
          </Button>
        </div>
      </motion.nav>

      <div className="relative z-10">{children}</div>
    </main>
  )
}
