import { Input } from '../ui/input'
import { cn, formatCurrencyInput, parseVndInput } from '../../lib/utils'

type CurrencyInputProps = {
  id?: string
  value: number
  onValueChange: (value: number) => void
  disabled?: boolean
  className?: string
  placeholder?: string
}

export function CurrencyInput({
  id,
  value,
  onValueChange,
  disabled,
  className,
  placeholder = '0',
}: CurrencyInputProps) {
  return (
    <div className="relative">
      <Input
        id={id}
        inputMode="numeric"
        value={value > 0 ? formatCurrencyInput(value) : ''}
        onChange={(event) => onValueChange(parseVndInput(event.target.value))}
        disabled={disabled}
        placeholder={placeholder}
        className={cn('pr-14 font-semibold tabular-nums', className)}
      />
      <span className="pointer-events-none absolute inset-y-0 right-3 flex items-center text-xs font-semibold text-slate-400">
        VND
      </span>
    </div>
  )
}
