'use client'

import type { ReactNode } from 'react'
import { useEffect } from 'react'
import { usePathname, useRouter } from 'next/navigation'
import { Loader2, ShieldCheck } from 'lucide-react'
import { motion } from 'motion/react'
import { authClient } from '../../lib/auth-client'

type ProtectedRouteProps = {
  children: ReactNode
}

export function ProtectedRoute({ children }: ProtectedRouteProps) {
  const pathname = usePathname()
  const router = useRouter()
  const { data: session, isPending } = authClient.useSession()
  const isAuthenticated = Boolean(session?.user)

  useEffect(() => {
    if (!isPending && !isAuthenticated) {
      router.replace(`/login?next=${encodeURIComponent(pathname || '/app')}`)
    }
  }, [isAuthenticated, isPending, pathname, router])

  if (isPending || !isAuthenticated) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-console text-slate-950">
        <motion.div
          initial={{ opacity: 0, scale: 0.96, y: 10 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          className="flex items-center gap-3 rounded-lg border border-white/70 bg-white/80 px-5 py-4 shadow-glass backdrop-blur-xl"
        >
          <span className="flex h-10 w-10 items-center justify-center rounded-lg bg-shopee text-white shadow-brand">
            <ShieldCheck className="h-5 w-5" />
          </span>
          <div>
            <p className="text-sm font-black text-slate-950">Checking session</p>
            <p className="text-xs font-medium text-slate-500">Shopee Pricing Desk</p>
          </div>
          <Loader2 className="h-4 w-4 animate-spin text-shopee" />
        </motion.div>
      </div>
    )
  }

  return children
}
