import type { ReactNode } from 'react'
import { Check, Clipboard, Coins, TrendingUp } from 'lucide-react'
import { motion } from 'motion/react'
import { useMemo, useState } from 'react'
import { type PricingResult } from '../../lib/pricing'
import { formatPlainPercent, formatRatePercent, formatVnd } from '../../lib/utils'
import { Badge } from '../ui/badge'
import { Button } from '../ui/button'
import { Card, CardContent } from '../ui/card'

type ResultCardProps = {
  result: PricingResult
  categoryFeeRate: number
}

export function ResultCard({ result, categoryFeeRate }: ResultCardProps) {
  const [copied, setCopied] = useState(false)
  const transitionKey = useMemo(
    () =>
      [
        result.suggestedPrice,
        result.categoryFee,
        result.paymentFee,
        result.serviceFee,
        result.shippingPaymentFee,
      ].join('-'),
    [result],
  )
  const feeShare =
    result.suggestedPrice > 0
      ? Math.min(100, (result.totalFees / result.suggestedPrice) * 100)
      : 0

  async function copyPrice() {
    const text = String(Math.round(result.suggestedPrice))

    try {
      await navigator.clipboard.writeText(text)
      setCopied(true)
      window.setTimeout(() => setCopied(false), 1400)
    } catch {
      setCopied(false)
    }
  }

  if (!result.isValid) {
    return (
      <Card className="min-h-full overflow-hidden">
        <CardContent className="flex min-h-[420px] items-center justify-center p-8 text-center">
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            className="max-w-sm space-y-3"
          >
            <Badge className="border-red-200 bg-red-50/90 text-red-600">
              Invalid fee setup
            </Badge>
            <p className="text-sm text-slate-600">
              Tổng phần trăm phí đang lớn hơn hoặc bằng 100%, nên không thể tính giá
              bán hợp lệ.
            </p>
          </motion.div>
        </CardContent>
      </Card>
    )
  }

  return (
    <Card className="min-h-full overflow-hidden">
      <div className="number-sheen relative overflow-hidden bg-[linear-gradient(135deg,#C53A21_0%,#EE4D2D_42%,#FF8A4C_100%)] px-6 py-8 text-center text-white">
        <div className="pointer-events-none absolute inset-0 bg-[linear-gradient(120deg,rgba(255,255,255,0.24),transparent_36%,rgba(255,255,255,0.16))]" />
        <div className="relative">
          <p className="text-xs font-black uppercase tracking-[0.2em] text-white/82">
            GIÁ BÁN GỢI Ý
          </p>
          <motion.div
          key={`price-${transitionKey}`}
            initial={{ opacity: 0, y: 12, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            transition={{ duration: 0.28, ease: [0.22, 1, 0.36, 1] }}
            className="mt-3 text-4xl font-black leading-tight tracking-tight sm:text-5xl"
          >
            {formatVnd(result.suggestedPrice)}
          </motion.div>
          <Button
            type="button"
            variant="secondary"
            className="mt-5 bg-white text-shopee hover:bg-orange-50"
            onClick={copyPrice}
          >
            {copied ? <Check className="h-4 w-4" /> : <Clipboard className="h-4 w-4" />}
            {copied ? 'Copied' : 'Copy Price'}
          </Button>
        </div>
      </div>

      <CardContent className="space-y-6 p-5 sm:p-6">
        <div className="rounded-lg border border-white/75 bg-white/58 p-4 shadow-soft">
          <div className="mb-3 flex items-center justify-between gap-4">
            <p className="text-xs font-black uppercase tracking-[0.18em] text-slate-500">
              Fee load
            </p>
            <p className="text-sm font-black tabular-nums text-slate-900">
              {feeShare.toFixed(1)}%
            </p>
          </div>
          <div className="h-2.5 overflow-hidden rounded-full bg-slate-200/80 shadow-inner">
            <motion.div
              key={`fee-share-${transitionKey}`}
              initial={{ width: 0 }}
              animate={{ width: `${feeShare}%` }}
              transition={{ duration: 0.48, ease: [0.22, 1, 0.36, 1] }}
              className="h-full rounded-full bg-[linear-gradient(90deg,#EE4D2D,#FFB199,#06B6D4)]"
            />
          </div>
        </div>

        <motion.div
          key={`breakdown-${transitionKey}`}
          initial="hidden"
          animate="show"
          variants={{
            hidden: { opacity: 0 },
            show: {
              opacity: 1,
              transition: { staggerChildren: 0.045 },
            },
          }}
          className="space-y-4"
        >
          <FeeRow
            label={`Phí ngành hàng (${formatRatePercent(categoryFeeRate)})`}
            value={result.categoryFee}
          />
          <FeeRow label="Phí thanh toán (6.0%)" value={result.paymentFee} />
          <FeeRow label="Phí dịch vụ (Cố định)" value={result.serviceFee} />
          <FeeRow
            label="Phí thu trên tiền Ship (nếu có)"
            value={result.shippingPaymentFee}
          />

          <div className="border-t border-dashed border-slate-200 pt-4">
            <FeeRow label="Tổng phí Shopee" value={result.totalFees} total />
          </div>
        </motion.div>

        <div className="grid gap-3">
          <SummaryBox
            icon={<Coins className="h-5 w-5" />}
            label="Doanh thu đơn hàng"
            value={formatVnd(result.sellerRevenue)}
            className="border-blue-200 bg-blue-50 text-blue-900"
          />
          <SummaryBox
            icon={<TrendingUp className="h-5 w-5" />}
            label="LỢI NHUẬN RÒNG"
            value={`${formatVnd(result.netProfit)} (~ ${formatPlainPercent(
              result.marginPercent,
            )} margin)`}
            className="border-emerald-200 bg-emerald-50 text-emerald-900"
          />
        </div>
      </CardContent>
    </Card>
  )
}

function FeeRow({
  label,
  value,
  total,
}: {
  label: string
  value: number
  total?: boolean
}) {
  return (
    <motion.div
      variants={{
        hidden: { opacity: 0, x: 10 },
        show: { opacity: 1, x: 0 },
      }}
      className="flex items-center justify-between gap-4 text-sm"
    >
      <span className={total ? 'font-bold text-slate-950' : 'text-slate-600'}>
        {label}
      </span>
      <span
        className={
          total
            ? 'font-black tabular-nums text-red-600'
            : 'font-semibold tabular-nums text-red-500'
        }
      >
        -{formatVnd(value)}
      </span>
    </motion.div>
  )
}

function SummaryBox({
  icon,
  label,
  value,
  className,
}: {
  icon: ReactNode
  label: string
  value: string
  className?: string
}) {
  return (
    <motion.div
      whileHover={{ y: -2 }}
      transition={{ duration: 0.18 }}
      className={`rounded-lg border p-4 shadow-soft ${className ?? ''}`}
    >
      <div className="flex items-center justify-between gap-4">
        <div className="flex items-center gap-2 text-sm font-bold">
          {icon}
          <span>{label}</span>
        </div>
        <p className="text-right text-lg font-black tabular-nums">{value}</p>
      </div>
    </motion.div>
  )
}
