const BASIS_POINTS = 10_000n
const PAYMENT_FEE_BPS = 600n

export const PAYMENT_FEE_RATE = 0.06
export const DEFAULT_SERVICE_FEE = 53_000

export type PricingInput = {
  cogs: number
  targetProfit: number
  categoryFeeRate: number
  serviceFee: number
  buyerShipping: number
}

export type PricingResult = {
  isValid: boolean
  suggestedPrice: number
  categoryFee: number
  paymentFee: number
  serviceFee: number
  shippingPaymentFee: number
  totalFees: number
  sellerRevenue: number
  netProfit: number
  marginPercent: number
  denominatorPercent: number
}

function toVndBigInt(value: number) {
  if (!Number.isFinite(value)) return 0n
  return BigInt(Math.max(0, Math.round(value)))
}

function ceilDiv(numerator: bigint, denominator: bigint) {
  if (denominator <= 0n) return 0n
  return (numerator + denominator - 1n) / denominator
}

function toNumber(value: bigint) {
  return Number(value)
}

export function calculateShopeePrice(input: PricingInput): PricingResult {
  const categoryFeeBps = BigInt(Math.round(input.categoryFeeRate * 10_000))
  const denominatorBps = BASIS_POINTS - categoryFeeBps - PAYMENT_FEE_BPS

  if (denominatorBps <= 0n) {
    return {
      isValid: false,
      suggestedPrice: 0,
      categoryFee: 0,
      paymentFee: 0,
      serviceFee: 0,
      shippingPaymentFee: 0,
      totalFees: 0,
      sellerRevenue: 0,
      netProfit: 0,
      marginPercent: 0,
      denominatorPercent: 0,
    }
  }

  const cogs = toVndBigInt(input.cogs)
  const targetProfit = toVndBigInt(input.targetProfit)
  const serviceFee = toVndBigInt(input.serviceFee)
  const buyerShipping = toVndBigInt(input.buyerShipping)
  const shippingPaymentFee = ceilDiv(buyerShipping * PAYMENT_FEE_BPS, BASIS_POINTS)
  const numerator = cogs + targetProfit + serviceFee + shippingPaymentFee
  const suggestedPrice = ceilDiv(numerator * BASIS_POINTS, denominatorBps)

  const categoryFee = ceilDiv(suggestedPrice * categoryFeeBps, BASIS_POINTS)
  const paymentFee = ceilDiv(suggestedPrice * PAYMENT_FEE_BPS, BASIS_POINTS)
  const totalFees = categoryFee + paymentFee + serviceFee + shippingPaymentFee
  const sellerRevenue = suggestedPrice - totalFees
  const netProfit = sellerRevenue - cogs
  const marginBps =
    suggestedPrice > 0n ? (netProfit * BASIS_POINTS) / suggestedPrice : 0n

  return {
    isValid: true,
    suggestedPrice: toNumber(suggestedPrice),
    categoryFee: toNumber(categoryFee),
    paymentFee: toNumber(paymentFee),
    serviceFee: toNumber(serviceFee),
    shippingPaymentFee: toNumber(shippingPaymentFee),
    totalFees: toNumber(totalFees),
    sellerRevenue: toNumber(sellerRevenue),
    netProfit: toNumber(netProfit),
    marginPercent: Number(marginBps) / 100,
    denominatorPercent: Number(denominatorBps) / 100,
  }
}
