'use client'

import { useMemo, useState } from 'react'
import { BarChart3, ShieldCheck, Sparkles } from 'lucide-react'
import { motion } from 'motion/react'
import { categories, type ShopType } from '../../data/categories'
import { calculateShopeePrice, DEFAULT_SERVICE_FEE } from '../../lib/pricing'
import { clamp, formatRatePercent, toWholeVnd } from '../../lib/utils'
import { Badge } from '../ui/badge'
import { InputCard, type ProfitMode } from './InputCard'
import { ResultCard } from './ResultCard'

export function CalculatorLayout() {
  const [shopType, setShopType] = useState<ShopType>('normal')
  const [categoryIndex, setCategoryIndex] = useState(1)
  const [cogs, setCogs] = useState(12_500_000)
  const [profitMode, setProfitMode] = useState<ProfitMode>('percent')
  const [profitPercent, setProfitPercent] = useState(12)
  const [profitAmount, setProfitAmount] = useState(1_500_000)
  const [serviceFeeEnabled, setServiceFeeEnabled] = useState(true)
  const [serviceFee, setServiceFee] = useState(DEFAULT_SERVICE_FEE)
  const [buyerShipping, setBuyerShipping] = useState(0)

  const selectedCategory = categories[categoryIndex] ?? categories[0]
  const categoryFeeRate = selectedCategory[shopType]
  const activeProfitAmount =
    profitMode === 'percent' ? toWholeVnd((cogs * profitPercent) / 100) : profitAmount
  const activeProfitPercent = cogs > 0 ? (activeProfitAmount / cogs) * 100 : 0
  const visibleProfitPercent =
    profitMode === 'percent' ? profitPercent : activeProfitPercent

  const pricingInput = useMemo(
    () => ({
      cogs,
      targetProfit: activeProfitAmount,
      categoryFeeRate,
      serviceFee: serviceFeeEnabled ? serviceFee : 0,
      buyerShipping,
    }),
    [
      cogs,
      activeProfitAmount,
      categoryFeeRate,
      serviceFeeEnabled,
      serviceFee,
      buyerShipping,
    ],
  )

  const result = useMemo(() => calculateShopeePrice(pricingInput), [pricingInput])

  function handleProfitModeChange(nextMode: ProfitMode) {
    if (nextMode === profitMode) return

    if (nextMode === 'amount') {
      setProfitAmount(activeProfitAmount)
    } else {
      setProfitPercent(clamp(activeProfitPercent, 0, 50))
    }

    setProfitMode(nextMode)
  }

  function handleProfitPercentChange(value: number) {
    const percent = clamp(value, 0, 50)

    if (profitMode === 'amount') {
      setProfitAmount(toWholeVnd((cogs * percent) / 100))
      return
    }

    setProfitPercent(percent)
  }

  return (
    <section className="px-4 pb-8 sm:px-6 lg:px-8">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.55, ease: [0.22, 1, 0.36, 1] }}
        className="mx-auto flex w-full max-w-7xl flex-col"
      >
        <header className="mb-6 grid gap-5 lg:grid-cols-[minmax(0,1fr)_auto] lg:items-end">
          <div>
            <Badge className="border-shopee/15 bg-white/70 text-shopee">
              <Sparkles className="mr-1.5 h-3.5 w-3.5" />
              Electronics retail pricing desk
            </Badge>
            <h1 className="mt-3 max-w-3xl text-4xl font-black leading-[0.98] tracking-tight text-slate-950 sm:text-5xl">
              Shopee Reverse Pricing Calculator
            </h1>
            <p className="mt-3 max-w-2xl text-sm font-semibold leading-6 text-slate-600 sm:text-base">
              High-ticket electronics margin workspace.
            </p>
          </div>

          <div className="grid gap-3 sm:grid-cols-2 lg:w-[360px]">
            <Badge className="justify-center border-blue-200/80 bg-blue-50/80 px-3 py-2 text-blue-700">
              <ShieldCheck className="mr-1.5 h-3.5 w-3.5" />
              Payment fee {formatRatePercent(0.06)}
            </Badge>
            <Badge className="justify-center border-emerald-200/80 bg-emerald-50/80 px-3 py-2 text-emerald-700">
              <BarChart3 className="mr-1.5 h-3.5 w-3.5" />
              {formatRatePercent(categoryFeeRate)} category
            </Badge>
          </div>
        </header>

        <div className="grid flex-1 gap-6 lg:grid-cols-[minmax(0,1.04fr)_minmax(380px,0.96fr)] lg:items-start">
          <motion.div
            initial={{ opacity: 0, x: -24 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.12, duration: 0.55, ease: [0.22, 1, 0.36, 1] }}
          >
            <InputCard
              shopType={shopType}
              onShopTypeChange={setShopType}
              categoryIndex={categoryIndex}
              onCategoryChange={setCategoryIndex}
              cogs={cogs}
              onCogsChange={(value) => setCogs(toWholeVnd(value))}
              profitMode={profitMode}
              onProfitModeChange={handleProfitModeChange}
              profitPercent={visibleProfitPercent}
              onProfitPercentChange={handleProfitPercentChange}
              profitAmount={profitAmount}
              onProfitAmountChange={(value) => setProfitAmount(toWholeVnd(value))}
              serviceFeeEnabled={serviceFeeEnabled}
              onServiceFeeEnabledChange={setServiceFeeEnabled}
              serviceFee={serviceFee}
              onServiceFeeChange={(value) => setServiceFee(toWholeVnd(value))}
              buyerShipping={buyerShipping}
              onBuyerShippingChange={(value) => setBuyerShipping(toWholeVnd(value))}
              pricingInput={pricingInput}
            />
          </motion.div>

          <motion.div
            initial={{ opacity: 0, x: 24 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: 0.2, duration: 0.55, ease: [0.22, 1, 0.36, 1] }}
            className="lg:sticky lg:top-6"
          >
            <ResultCard result={result} categoryFeeRate={categoryFeeRate} />
          </motion.div>
        </div>
      </motion.div>
    </section>
  )
}
